"""Original, elementary geometry assessment packs; four parallel variants.

The referenced repository maps establish topic alignment, not exercise copying
or a claim to cover each textbook in full. Proofs require a teacher's reading.
"""
from pathlib import Path
import json
import sympy as s

ROOT = Path(__file__).resolve().parents[2]
AT = 'geometry-course/textbook/source-inventory.json'
ME = 'geometry-merzlyak/data/course.json'
PO = 'geometry-pogorelov/data/course.json'
ST = 'stereo-course/textbook/source-index.json'
M10 = 'stereo-course/merzlyak-10-base/source-index.json'
SH = 'stereo-course/shestakov-yaschenko-10-11/data/source-index.json'


def show(value):
    return str(s.sympify(value)).replace('**2', '²').replace('**3', '³').replace('*pi', 'π').replace('pi', 'π').replace('sqrt(', '√(').replace('*', '·')


def num(q, expr, value, solution, unit=''):
    expected = str(s.sympify(value))
    assert s.simplify(s.sympify(expr) - s.sympify(expected)) == 0, (q, expr, value)
    return {'q': q, 'a': show(value) + ((' ' + unit) if unit else ''),
            'solution': solution, 'points': 2,
            'check': {'kind': 'expression', 'expr': str(expr), 'expected': expected}}


def proof(q, answer, solution):
    return {'q': q, 'a': answer, 'solution': solution, 'points': 2,
            'check': {'kind': 'manual', 'reason': solution}}


def listing(q, answer, solution):
    return proof(q, answer, solution)


def pack(slug, title, grade, refs, maker, spatial=False, include_m10=False):
    names = {AT: 'Атанасян и др. Геометрия 7–9, 2023',
             ME: 'Мерзляк, Полонский, Якир. Геометрия 7–9 (издания 2015/2013/2022)',
             PO: 'Погорелов. Геометрия 7–9, 2022',
             ST: 'Атанасян и др. Геометрия 10–11, 2024',
             SH: 'Шестаков, Ященко. Геометрия. Сборник задач 10–11, 2021',
             M10: 'Мерзляк и др. Геометрия 10. Базовый уровень, 2022'}
    books = [names[path] for path, _ in refs]
    vs = []
    for k in range(1, 5):
        sr, kr = maker(k)
        if slug in ('prostranstvo-parallelnost', 'prostranstvo-perpendikulyarnost'):
            # Keep the conventional cube name while changing which edges and
            # vertices are investigated in each parallel assessment variant.
            cycle = 'ABCD'
            trans = str.maketrans({c: cycle[(i+k-1) % 4] for i, c in enumerate(cycle)})
            full = 'ABCDA₁B₁C₁D₁'
            rotated = full.translate(trans)
            def relabel(text):
                return text.translate(trans).replace(rotated, full)
            for t in sr + kr:
                for field in ('q', 'a', 'solution'):
                    t[field] = relabel(t[field])
                if t['check']['kind'] == 'manual':
                    t['check']['reason'] = relabel(t['check']['reason'])
        assert len(sr) == 4 and len(kr) == 5
        for i, t in enumerate(sr):
            t['points'] = [1, 1, 2, 2][i]
        for t in kr:
            t['points'] = 2
        vs.append({'name': str(k), 'sr': sr, 'kr': kr})
    note = 'Проверка основных навыков указанной темы. Это авторские задания, а не копии упражнений и не полный годовой комплект к учебнику. Порядок тем у авторов различается: проводить после изучения всех проверяемых свойств.'
    book_grades = None
    if slug in ('ploshchadi', 'podobie', 'vpisannye-ugly'):
        note += ' В программе Погорелова эта тема относится к 9 классу; по Атанасяну и Мерзляку — к 8 классу.'
        grade = '8–9'
        book_grades = {names[path]: [9 if path == PO else 8] for path, _ in refs}
    result = {'id': 'geo-' + slug, 'title': title, 'grade': f'{grade} класс',
            'subject': 'Геометрия', 'books': books,
            'source_refs': [{'path': path, 'sections': sect} for path, sect in refs],
            'scope_note': note,
            'instruction': 'Выполните чертежи к геометрическим задачам. Запишите формулу или свойство и ход решения. Чертеж не заменяет доказательство. Точные ответы с π и корнями не округляйте.',
            'sr_minutes': 15, 'kr_minutes': 40, 'variants': vs}
    if book_grades is not None:
        result['book_grades'] = book_grades
    return result


def segments(k):
    a, b = k + 3, k + 5
    sr = [num(f'Точка B лежит между A и C. AB = {a} см, BC = {b} см. Найдите AC.', f'{a}+{b}', a+b, f'AC = AB + BC = {a+b} см.', 'см'),
          num(f'M — середина отрезка AB, AB = {2*b} см. Найдите AM.', f'{2*b}/2', b, f'Середина делит отрезок пополам: AM = AB : 2 = {b} см.', 'см'),
          num(f'B лежит между A и C. AC = {3*a} см, AB = {a} см. Найдите BC.', f'{3*a}-{a}', 2*a, f'BC = AC − AB = {2*a} см.', 'см'),
          num(f'Отрезок AB длиной {3*b} см разделен точкой M так, что AM вдвое больше MB. Найдите MB.', f'{3*b}/3', b, f'В отрезке 3 равные части: MB = AB : 3 = {b} см.', 'см')]
    kr = [num(f'На отрезке AC отмечена точка B. AB = {b+1} см, BC = {a+2} см. Найдите AC.', f'{b+1}+{a+2}', a+b+3, 'По свойству сложения отрезков AC = AB + BC.', 'см'),
          num(f'B лежит между A и C, AC = {4*b} см и BC = {b} см. Найдите AB.', f'{4*b}-{b}', 3*b, 'AB = AC − BC.', 'см'),
          num(f'M — середина AB. AM = {a+2} см. Найдите AB.', f'2*{a+2}', 2*(a+2), 'Обе половины равны AM: AB = 2AM.', 'см'),
          num(f'Точки A, B, C, D лежат на прямой именно в таком порядке. AB = {a} см, BC = {b} см, CD = {a+1} см. Найдите AD.', f'{a}+{b}+{a+1}', 2*a+b+1, 'AD = AB + BC + CD.', 'см'),
          proof(f'На отрезке AB длиной {2*(a+b)} см M — середина. Объясните, почему AM = MB, и найдите длины этих отрезков.', f'AM = MB = {a+b} см.', 'По определению середина делит отрезок на два равных отрезка. Каждый равен половине AB.')]
    return sr, kr


