    sr=[num(f'Треугольники ABC и DEF подобны, вершины соответствуют в указанном порядке. DE = 2AB. AB = {a} см. Найдите DE.',f'2*{a}',2*a,'Соответствующая сторона увеличивается в 2 раза.','см'),
        num(f'Два подобных треугольника имеют соответствующие стороны {a} и {3*a} см. Найдите отношение большей стороны к меньшей.',f'{3*a}/{a}',3,'Делим большую соответствующую сторону на меньшую.'),
        num(f'В подобных треугольниках все стороны второго в 2 раза больше соответствующих сторон первого. Периметр первого {3*b} см. Найдите периметр второго.',f'2*{3*b}',6*b,'Периметры относятся как соответствующие стороны.','см'),
        num(f'В треугольнике ABC отрезок MN соединяет середины AB и AC. BC = {2*b} см. Найдите MN.',f'{2*b}/2',b,'Средняя линия треугольника равна половине третьей стороны.','см')]
    kr=[num(f'Треугольники ABC и DEF подобны. DE = 3AB, EF = 3BC. BC = {b+1} см. Найдите EF.',f'3*{b+1}',3*(b+1),'Соответствующие стороны относятся с коэффициентом 3.','см'),
        num(f'Площадь треугольника {a*b} см². Все его стороны увеличили в 2 раза. Найдите площадь нового треугольника.',f'4*{a*b}',4*a*b,'При коэффициенте подобия 2 площади относятся как 2² = 4.','см²'),
        num(f'Соответствующие стороны подобных треугольников относятся как 1 : 3. Периметр большего {9*a} см. Найдите периметр меньшего.',f'{9*a}/3',3*a,'Периметры относятся как стороны.','см'),
        num(f'M и N — середины AB и AC треугольника ABC. MN = {b+2} см. Найдите BC.',f'2*{b+2}',2*(b+2),'Третья сторона вдвое длиннее средней линии.','см'),
        proof('В треугольниках ABC и DEF угол A равен углу D, угол B равен углу E. Докажите подобие треугольников.','Треугольники подобны по двум углам.','Две пары соответственных углов равны по условию. Применяем первый признак подобия треугольников.')]
    return sr,kr


