        num(f'Центральный угол AOB равен {a+10}°. Найдите меньшую дугу AB.',str(a+10),a+10,'Градусная мера меньшей дуги равна центральному углу менее 180°.','°'),
        num(f'Угол B вписанного четырехугольника ABCD равен {a+15}°. Найдите угол D.',f'180-{a+15}',165-a,'Противоположные углы в сумме дают 180°.','°'),
