def coordinates(k):
    a,b=k+1,k+2
    sr=[num(f'Точки A({a}; 0) и B({a+5}; 0) лежат на оси Ox. Найдите AB.',f'{a+5}-{a}',5,'На одной горизонтальной прямой длина равна модулю разности абсцисс.'),
        listing(f'Найдите координаты середины отрезка A(0; 0), B({2*a}; {2*b}).',f'({a}; {b}).','Каждая координата середины равна полусумме соответствующих координат концов.'),
        num(f'Найдите расстояние между A(0; 0) и B({3*k}; {4*k}).',f'sqrt({3*k}**2+{4*k}**2)',5*k,'AB = √((xB − xA)² + (yB − yA)²).'),
        listing(f'Окружность задана уравнением (x − {a})² + (y − {b})² = {a*a}. Укажите центр и радиус.',f'Центр ({a}; {b}), радиус {a}.','Сравниваем с уравнением (x − x0)² + (y − y0)² = R².')]
    kr=[num(f'Найдите расстояние между A({a}; {b}) и B({a+3}; {b+4}).','sqrt(3**2+4**2)',5,'Разности координат равны 3 и 4. Расстояние √(3² + 4²) = 5.'),
        listing(f'Найдите середину отрезка A({a}; {b}), B({a+4}; {b+6}).',f'({a+2}; {b+3}).','Складываем соответствующие координаты концов и делим каждую сумму на 2.'),
        listing(f'Запишите уравнение окружности с центром ({a}; 0) и радиусом {b}.',f'(x − {a})² + y² = {b*b}.','Подставляем координаты центра и R² в общее уравнение окружности.'),
        num(f'Точки A(0; 0), B({a}; 0), C({a}; {b}), D(0; {b}) — вершины прямоугольника. Найдите его площадь.',f'{a}*{b}',a*b,'Длины сторон по координатам равны a и b; площадь равна их произведению.'),
        proof(f'A({-a}; 0), B({a}; 0), C(0; {b}). Докажите, что треугольник ABC равнобедренный.','AC = BC.','По формуле расстояния AC² = a² + b² и BC² = a² + b². Расстояния положительны, следовательно AC = BC.')]
    return sr,kr


def vectors(k):
    a,b=k+1,k+2
    sr=[listing(f'Даны A(0; 0), B({a}; {b}). Найдите координаты вектора AB.',f'({a}; {b}).','Из координат конца B вычитаем координаты начала A.'),
        listing(f'Найдите сумму векторов u = ({a}; 1) и v = (2; {b}).',f'({a+2}; {b+1}).','Складываем соответствующие координаты.'),
        listing(f'Найдите координаты 2u, если u = ({a}; {b}).',f'({2*a}; {2*b}).','При умножении вектора на 2 обе координаты умножаются на 2.'),
        num(f'Вектор u = ({3*k}; {4*k}). Найдите его длину.',f'sqrt({3*k}**2+{4*k}**2)',5*k,'Длина равна √(x² + y²).')]
    kr=[listing(f'Даны A(1; 2), B({a+1}; {b+2}). Найдите вектор AB.',f'({a}; {b}).','Вычитаем координаты начала из координат конца.'),
        listing(f'u = ({a}; {b}), v = (1; 2). Найдите u − v.',f'({a-1}; {b-2}).','Вычитаем соответствующие координаты.'),
        num(f'u = ({a}; 0), v = ({b}; 0). Найдите их скалярное произведение.',f'{a}*{b}',a*b,'u·v = uxvx + uyvy.'),
        num(f'Вектор u = (0; {b+2}). Найдите его длину.',str(b+2),b+2,'Длина вертикального вектора равна модулю ненулевой координаты.'),
        proof('Для любых трех точек A, B, C докажите равенство векторов AB + BC = AC.','AB + BC = AC.','Последовательный переход из A в B и затем из B в C дает тот же результирующий перенос, что переход из A в C. Это правило треугольника сложения векторов.')]
    return sr,kr


def trig(k):
    n=k
    sr=[num(f'В прямоугольном треугольнике катет, противолежащий углу α, равен {3*n} см, гипотенуза {5*n} см. Найдите sin α.',f'{3*n}/{5*n}',s.Rational(3,5),'Синус — отношение противолежащего катета к гипотенузе.'),
        num(f'Катет, прилежащий к острому углу α, равен {4*n} см, гипотенуза {5*n} см. Найдите cos α.',f'{4*n}/{5*n}',s.Rational(4,5),'Косинус — отношение прилежащего катета к гипотенузе.'),
        num(f'В прямоугольном треугольнике катеты, противолежащий и прилежащий к углу α, равны {3*n} и {4*n} см соответственно. Найдите tg α.',f'{3*n}/{4*n}',s.Rational(3,4),'Тангенс — отношение противолежащего катета к прилежащему.'),
        num(f'Гипотенуза прямоугольного треугольника {10*n} см, sin α = 1/2. Найдите катет, противолежащий углу α.',f'{10*n}/2',5*n,'Противолежащий катет равен произведению гипотенузы на sin α.','см')]
    kr=[num(f'Катет, противолежащий острому углу α, равен {5*n} см, гипотенуза {13*n} см. Найдите sin α.',f'{5*n}/{13*n}',s.Rational(5,13),'По определению sin α = противолежащий катет / гипотенуза.'),
        num(f'Гипотенуза {10*n+10} см, cos α = 1/2. Найдите катет, прилежащий к углу α.',f'{10*n+10}/2',5*n+5,'Прилежащий катет = гипотенуза · cos α.','см'),
        num(f'Катет, прилежащий к острому углу α, равен {4*n} см, tg α = 3/4. Найдите противолежащий катет.',f'{4*n}*3/4',3*n,'Противолежащий катет = прилежащий · tg α.','см'),
        num(f'В прямоугольном треугольнике гипотенуза {2*(n+3)} см и острый угол 30°. Найдите противолежащий этому углу катет.',f'{2*(n+3)}/2',n+3,'sin 30° = 1/2. Катет равен половине гипотенузы.','см'),
        proof('В прямоугольном треугольнике для острого угла α докажите sin² α + cos² α = 1.','sin² α + cos² α = 1.','Если a — противолежащий катет, b — прилежащий, c — гипотенуза, то сумма квадратов отношений равна (a² + b²)/c². По теореме Пифагора числитель равен c².')]
    return sr,kr


