        num(f'Радиус цилиндра {r} см, высота {h+1} см. Найдите площадь полной поверхности.',f'2*pi*{r}*({r}+{h+1})',f'{2*r*(r+h+1)}*pi','Sполн = 2πR² + 2πRh.','см²'),
