        num(f'Радиус цилиндра {r+1} см, высота {h+3} см. Найдите Sполн.',f'2*pi*{r+1}*({r+1}+{h+3})',f'{2*(r+1)*(r+h+4)}*pi','Sполн = 2πR(R + h).','см²'),
